/**
 * Tracés de glyphes, extraits une fois pour toutes de polices libres (SIL Open
 * Font License 1.1) puis figés ici en données de chemin SVG : le cadran se
 * dessine à l'identique sur tout appareil, sans dépendre d'une police installée,
 * et la rastérisation côté serveur n'a rien à charger.
 *
 *   - chiffres arabes orientaux : Noto Naskh Arabic Bold (The Noto Project Authors)
 *   - écriture manuscrite et phrase : Caveat 400 (The Caveat Project Authors)
 *   - « Automatique » en cursive : Pinyon Script (The Pinyon Script Project Authors)
 *
 * Repère de chaque tracé : unités de la police (`upm` par em), y vers le bas, la
 * ligne de base à y = 0 ; `box` = [xmin, ymin, xmax, ymax] de l'encre.
 */

export interface Glyphe {
  /** Avance horizontale, en unités de police. */
  adv: number;
  box: [number, number, number, number];
  d: string;
}

export interface Ligne {
  upm: number;
  box: [number, number, number, number];
  d: string;
}

export interface JeuDeChiffres {
  upm: number;
  digits: Record<string, Glyphe>;
}

